const message = $input.first().json.message;
const caption = message?.caption || '';
const adminChatId = message?.chat?.id;

// Get highest quality photo (last in array)
const photos = message?.photo || [];
const bestPhoto = photos[photos.length - 1];
const fileId = bestPhoto?.file_id;

if (!fileId) {
  return [{ json: { error: 'no_photo_file_id', adminChatId } }];
}

if (!caption.startsWith('/broadcast')) {
  return [{ json: { error: 'missing_broadcast_command_in_caption', adminChatId, 
    help: 'Send photo with caption: /broadcast [tag]' } }];
}

const rest = caption.replace('/broadcast', '').trim();

const ALLOWED_TAGS = ['active client', 'potential client', 'high potential', 'past client', 'cold', 'warm'];
let matchedTag = null;
for (const tag of ALLOWED_TAGS) {
  if (rest.toLowerCase().startsWith(tag)) {
    matchedTag = tag;
    break;
  }
}

if (!matchedTag) {
  return [{ json: { error: 'invalid_tag', raw: rest, adminChatId } }];
}

return [{ json: { 
  tag: matchedTag,
  file_id: fileId,
  adminChatId,
  parsed_ok: true
} }];
